function overviewExportName(extension){const period=overviewExportLabel.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/gi,"-").replace(/^-|-$/g,"").toLowerCase()||"periodo";return`historico-movimentacoes-${period}.${extension}`}
function exportOverviewHistory(format){if(!overviewExportEntries.length){toast("Não há movimentações para exportar neste período.",true);return}if(format==="excel"){const rows=overviewExportEntries.map(entry=>`<tr><td>${esc(entry.type)}</td><td>${esc(entry.description)}</td><td>${esc(entry.detail)}</td><td>${esc(entry.payment)}</td><td>${date(entry.created_at)}</td><td style="mso-number-format:'0.00'">${Number(entry.amount||0).toFixed(2).replace(".",",")}</td></tr>`).join(""),content=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="UTF-8"><style>td,th{border:1px solid #ccc;padding:6px}th{background:#eee}</style></head><body><table><tr><th colspan="6">Histórico de movimentações · ${esc(overviewExportOperation)} · ${esc(overviewExportLabel)}</th></tr><tr><th>Tipo</th><th>Descrição</th><th>Detalhe</th><th>Pagamento</th><th>Data e horário</th><th>Valor</th></tr>${rows}</table></body></html>`,url=URL.createObjectURL(new Blob(["\ufeff",content],{type:"application/vnd.ms-excel;charset=utf-8"})),link=document.createElement("a");link.href=url;link.download=overviewExportName("xls");link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}const report=window.open("","_blank");if(!report){toast("Permita pop-ups para exportar o PDF.",true);return}const total=overviewExportEntries.reduce((sum,entry)=>sum+Number(entry.amount||0),0),rows=overviewExportEntries.map(entry=>`<tr><td>${esc(entry.type)}</td><td><b>${esc(entry.description)}</b><small>${esc(entry.detail)}</small></td><td>${esc(entry.payment)}</td><td>${date(entry.created_at)}</td><td class="value">${entry.amount<0?"− ":""}${money(Math.abs(entry.amount))}</td></tr>`).join("");report.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(overviewExportName("pdf"))}</title><style>@page{size:A4;margin:14mm}body{font:12px Arial,sans-serif;color:#222}h1{font-size:22px;margin:0 0 5px}p{margin:0 0 18px;color:#555}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left;vertical-align:top}th{font-size:10px;text-transform:uppercase;background:#f3f3f3}small{display:block;margin-top:3px;color:#666}.value{text-align:right;white-space:nowrap}tfoot td{font-weight:bold;border-top:2px solid #222}@media print{button{display:none}}</style></head><body><h1>Histórico de movimentações</h1><p>${esc(overviewExportOperation)} · ${esc(overviewExportLabel)} · ${overviewExportEntries.length} registros</p><table><thead><tr><th>Tipo</th><th>Descrição</th><th>Pagamento</th><th>Data e horário</th><th>Valor</th></tr></thead><tbody>${rows}</tbody><tfoot><tr><td colspan="4">Saldo das movimentações</td><td class="value">${money(total)}</td></tr></tfoot></table><script>addEventListener('load',()=>setTimeout(()=>print(),200));<\/script></body></html>`);report.document.close()}
function menuPage(){return heading("Cardápio",`<button class="primary" data-new-menu>+ Cadastrar</button>`)+`<div class="notice"><b>Baixa automática:</b> configure em cada item quais produtos do estoque são consumidos quando uma unidade é vendida na Frente de Caixa.</div><div class="cards">${entries(data.menu).map(([id,m])=>{const componentCount=data.recipes[id]?.components?.length||0;return`<article class="card"><h3>${esc(m.name)}</h3><div class="price">${money(m.price)}</div><p class="muted">${category(m)} · ${componentCount?`${componentCount} insumo${componentCount===1?"":"s"} vinculado${componentCount===1?"":"s"}`:"Sem insumos vinculados"}</p><span class="status ${componentCount?'printed':'pending'}">${componentCount?'Baixa de estoque ativa':'Sem baixa automática'}</span><div class="actions menu-stock-actions"><button data-edit-menu="${id}">Editar</button><button class="danger" data-delete-menu="${id}">Remover</button></div></article>`}).join("")}</div>`}
