function menuDialog(id=""){const m=data.menu[id]||{},recipe=data.recipes[id],hasStockItems=entries(data.stock_items).length>0,components=recipe?.components||[],menuCategory=category(m);openModal(`<h2>${id?"Editar":"Cadastrar"} item</h2><form data-form="menu"><input type="hidden" name="id" value="${id}"><div class="field"><label>Nome</label><input name="name" value="${esc(m.name||"")}" required></div><div class="form-row"><div class="field"><label>Preço de venda</label><input name="price" type="number" min="0" step=".01" value="${m.price??0}" required></div><div class="field"><label>Categoria</label><select name="category"><option ${menuCategory==="Bebidas"?"selected":""}>Bebidas</option><option ${menuCategory==="Comidas"?"selected":""}>Comidas</option></select></div></div><section class="menu-recipe-section"><div><span class="eyebrow">Baixa automática de estoque</span><h3>Insumos utilizados</h3><p class="muted">Informe quanto de cada insumo é consumido na venda de uma unidade deste produto.</p></div>${hasStockItems?`<div class="recipe-labels menu-recipe-labels"><span>Insumo</span><span>Consumo</span><span>Unidade</span><span>Custo</span></div><div data-recipe-components>${components.map(component=>menuRecipeComponentRow(component,menuCategory)).join("")}</div><button type="button" data-add-component>+ Adicionar insumo</button><div class="menu-recipe-cost"><span>Custo estimado deste item</span><b data-menu-recipe-total>${money(0)}</b></div>${components.length?"":`<p class="muted recipe-empty-hint">Nenhum insumo vinculado. O produto não movimentará o estoque.</p>`}`:`<div class="notice">Cadastre os insumos na área Estoque antes de vinculá-los ao produto.</div>`}</section><button class="primary checkout-button" type="submit">Salvar produto e insumos</button></form>`)}
function menuIngredientCost(quantity,inputUnit,item){const stockUnit=item?.unit||"un",factors={ml:{ml:1,L:.001},L:{ml:1000,L:1},g:{g:1,kg:.001},kg:{g:1000,kg:1}};let normalized=Number(quantity||0);if(inputUnit&&inputUnit!==stockUnit){const direct=factors[inputUnit]?.[stockUnit];if(direct)normalized*=direct;else{const packageFactor=factors[inputUnit]?.[item.package_measure],size=Number(item.package_size||0);if(!packageFactor||!size)return 0;normalized=normalized*packageFactor/size}}return normalized*Number(item?.cost_price||0)}
