function stockPage(){const products=entries(data.menu).sort((a,b)=>a[1].name.localeCompare(b[1].name)),controlled=products.filter(([,p])=>p.stock_controlled),low=controlled.filter(([,p])=>Number(p.stock_quantity||0)<=Number(p.stock_minimum||0)),units=controlled.reduce((s,[,p])=>s+Number(p.stock_quantity||0),0),value=controlled.reduce((s,[,p])=>s+Number(p.stock_quantity||0)*Number(p.cost_price||0),0),movements=entries(data.stock_movements).sort((a,b)=>(b[1].created_at||"").localeCompare(a[1].created_at||"")).slice(0,50);return heading("Controle de estoque",`<button class="primary" data-stock-entry>+ Nova movimentação</button>`)+`<div class="kpi-grid stock-kpis"><article class="kpi-card featured"><span>Valor em estoque</span><b>${money(value)}</b><small>Baseado no custo cadastrado</small></article><article class="kpi-card"><span>Itens controlados</span><b>${controlled.length}</b><small>de ${products.length} produtos</small></article><article class="kpi-card"><span>Unidades disponíveis</span><b>${units.toLocaleString("pt-BR")}</b><small>Saldo físico total</small></article><article class="kpi-card ${low.length?'stock-alert-card':''}"><span>Precisam de atenção</span><b>${low.length}</b><small>Abaixo do mínimo ou esgotados</small></article></div>${low.length?`<div class="notice stock-warning"><b>Reposição necessária:</b> ${low.map(([,p])=>esc(p.name)).join(", ")}.</div>`:""}<section class="dashboard-card stock-products"><div class="dashboard-card-head"><div><span class="eyebrow">Posição atual</span><h2>Produtos</h2></div><span class="muted">Saldo, mínimo e custo</span></div><div class="stock-table-wrap"><table><thead><tr><th>Produto</th><th>Status</th><th>Saldo</th><th>Mínimo</th><th>Custo</th><th>Valor</th><th></th></tr></thead><tbody>${products.map(([id,p])=>{const status=stockStatus(p),qty=Number(p.stock_quantity||0);return`<tr><td><b>${esc(p.name)}</b><small>${esc(p.sku||p.barcode||p.supplier||"Sem dados adicionais")}</small></td><td><span class="status ${status[1]}">${status[0]}</span></td><td><b>${p.stock_controlled?`${qty} ${esc(p.unit||"un")}`:"—"}</b></td><td>${p.stock_controlled?Number(p.stock_minimum||0):"—"}</td><td>${p.stock_controlled?money(p.cost_price):"—"}</td><td>${p.stock_controlled?money(qty*Number(p.cost_price||0)):"—"}</td><td><div class="actions"><button data-stock-move="${id}" ${p.stock_controlled?'':'disabled'}>Movimentar</button><button data-stock-config="${id}">Configurar</button></div></td></tr>`}).join("")}</tbody></table></div></section><section class="dashboard-card stock-history"><div class="dashboard-card-head"><div><span class="eyebrow">Auditoria</span><h2>Movimentações recentes</h2></div><span class="muted">Últimas 50</span></div><div class="movement-list">${movements.map(([,m])=>`<div><span class="stock-movement-sign ${Number(m.signed_quantity)>0?'in':'out'}">${Number(m.signed_quantity)>0?'+':''}${Number(m.signed_quantity)}</span><div><b>${esc(m.product_name)}</b><small>${esc({sale:"Venda",in:"Entrada",out:"Saída",loss:"Perda",return:"Devolução",adjustment_in:"Ajuste"}[m.type]||"Movimentação")} · ${esc(m.reason||"Sem motivo")} · ${esc(m.responsible||"Sistema")} · ${date(m.created_at)}</small></div><b>${Number(m.balance_before)} → ${Number(m.balance_after)}</b></div>`).join("")||empty("Nenhuma movimentação registrada.")}</div></section>`}
