  const low=items.filter(([,item])=>Number(item.stock_quantity||0)<=Number(item.stock_minimum||0)),available=items.filter(([,item])=>Number(item.stock_quantity||0)>0).length,openInventory=entries(data.inventories).find(([,inventory])=>inventory.status==="open");
