function parseInvoiceXml(content){const xml=new DOMParser().parseFromString(content,"application/xml");if(xml.querySelector("parsererror"))throw new Error("O arquivo XML está inválido.");const text=(root,tag)=>root.getElementsByTagName(tag)[0]?.textContent?.trim()||"",info=xml.getElementsByTagName("infNFe")[0];if(!info)throw new Error("O arquivo não parece ser uma NF-e válida.");const unitMap={UN:"un",UND:"un",UNID:"un",CX:"caixa",CAIXA:"caixa",KG:"kg",G:"g",LT:"L",L:"L",ML:"ml",GF:"garrafa",GFA:"garrafa",LATA:"lata"},supplier=text(xml.getElementsByTagName("emit")[0]||xml,"xNome"),invoiceNumber=text(xml,"nNF"),rawKey=(info.getAttribute("Id")||text(xml,"chNFe")).replace(/^NFe/,"");if(!rawKey)throw new Error("Não foi possível identificar a chave da NF-e.");const items=[...xml.getElementsByTagName("det")].map(det=>{const product=det.getElementsByTagName("prod")[0]||det,rawUnit=text(product,"uCom").toUpperCase(),barcode=text(product,"cEAN");return{name:text(product,"xProd"),sku:text(product,"cProd"),barcode:/^(SEM GTIN|0)$/i.test(barcode)?"":barcode,unit:unitMap[rawUnit]||"un",quantity:Number(text(product,"qCom")),unit_cost:Number(text(product,"vUnCom"))}}).filter(item=>item.name&&Number.isFinite(item.quantity)&&item.quantity>0&&Number.isFinite(item.unit_cost));if(!items.length)throw new Error("Nenhum produto válido foi encontrado na NF-e.");return{invoice_key:rawKey,invoice_number:invoiceNumber,supplier,items}}
