function cashLive(id,cash){const sales=cashSales(id),accountReceipts=cashAccountPayments(id),directSales=sales.filter(([,sale])=>!sale.account_id&&sale.payment_method!=="Caderneta"),accountSales=sales.filter(([,sale])=>sale.account_id||sale.payment_method==="Caderneta"),payments={};for(const[,sale]of directSales){const method=systemLabel(sale.payment_method||"Não informado");payments[method]=(payments[method]||0)+Number(sale.quantity)*Number(sale.price)}for(const[,receipt]of accountReceipts){const method=systemLabel(receipt.payment_method||"Não informado");payments[method]=(payments[method]||0)+Number(receipt.amount)}const valueOf=list=>list.reduce((sum,[,entry])=>sum+Number(entry.quantity||0)*Number(entry.price||0),0),directTotal=valueOf(directSales),accountCharges=valueOf(accountSales),salesTotal=directTotal+accountCharges,accountReceiptsTotal=accountReceipts.reduce((sum,[,receipt])=>sum+Number(receipt.amount||0),0),totalReceived=directTotal+accountReceiptsTotal,costTotal=sales.reduce((sum,[,sale])=>{if(Array.isArray(sale.stock_usage)&&sale.stock_usage.length)return sum+sale.stock_usage.reduce((cost,usage)=>cost+Number(usage.quantity||0)*Number(usage.unit_cost||0),0);return sum+Number(data.menu[sale.menu_id]?.cost_price||0)*Number(sale.quantity||0)},0),estimatedProfit=salesTotal-costTotal,supplies=(cash.movements||[]).filter(item=>item.type==="supply").reduce((sum,item)=>sum+Number(item.amount),0),withdrawals=(cash.movements||[]).filter(item=>item.type==="withdrawal").reduce((sum,item)=>sum+Number(item.amount),0),expected=Number(cash.opening_amount||0)+Number(payments.Dinheiro||0)+supplies-withdrawals,payable=entries(data.staff_shifts).filter(([,shift])=>shift.cash_session_id===id&&shift.status!=="paid"&&shift.status!=="cancelled").reduce((sum,[,shift])=>sum+Number(shift.daily_rate||0),0);return{sales,directSales,accountSales,accountReceipts,payments,directTotal,accountCharges,salesTotal,accountReceiptsTotal,totalReceived,costTotal,estimatedProfit,supplies,withdrawals,expected,receivable:accountCharges,payable,total:totalReceived}}
