document.addEventListener("change",async event=>{
  if(event.target.matches("[data-invoice-file]")){try{const file=event.target.files?.[0];if(!file)return;toast(file.type==="application/pdf"||/\.pdf$/i.test(file.name)?"Lendo o PDF...":"Lendo o XML...");const invoice=file.type==="application/pdf"||/\.pdf$/i.test(file.name)?await parseInvoicePdf(file):parseInvoiceXml(await file.text());invoicePreviewDialog(invoice)}catch(error){pendingInvoice=null;toast(error.message,true)}return}
  if(event.target.matches("[data-summary-cash]")&&event.target.value){summaryFilter=event.target.value;draw()}
  if(event.target.matches("[data-staff-cash]")){staffCashId=event.target.value;draw()}
  if(event.target.matches("[data-form='staff-shift'] [name='employee_id']")){const option=event.target.selectedOptions[0];event.target.form.elements.daily_rate.value=option?.dataset.rate||""}
  if(event.target.matches(".recipe-component [name='stock_item_id']")){const row=event.target.closest(".recipe-component"),item=data.stock_items[event.target.value],unitSelect=row.querySelector("[name='component_unit']");unitSelect.innerHTML=item?recipeUnitOptions(item,defaultRecipeUnit(item)):'<option value="">Unidade</option>';updateMenuRecipeCosts(event.target.form)}
  if(event.target.matches("[data-form='menu'] [name='component_unit']"))updateMenuRecipeCosts(event.target.form)
  if(event.target.matches("[data-form='menu'] [name='category']"))filterMenuIngredientOptions(event.target.form)
  if(event.target.matches("[data-form='checkout'] [name='destination'],[data-form='checkout'] [name='account_id'],[data-form='checkout'] [name='payment_method']"))updateCheckoutFields(event.target.form)
  if(event.target.matches("[data-form='account-payment'] [name='settlement_type'],[data-form='account-payment'] [name='payment_method'],[data-form='account-payment'] [data-allocation-toggle]")){if(event.target.matches("[data-allocation-toggle]")&&event.target.checked){const input=event.target.parentElement.querySelector("[data-allocation-item]");if(input.value===""||Number(input.value)<=0)input.value="1"}updateAccountPaymentFields(event.target.form)}
  if(event.target.matches("[data-form='stock-purchase'] [data-purchase-item]"))updateStockPurchaseFields(event.target.form)
  if(event.target.matches("[data-form='stock-purchase'] [name='purchase_unit']"))updatePurchasePackageFields(event.target.form)
  if(event.target.matches("[data-form='stock-purchase-line'] [data-batch-purchase-item]")){const form=event.target.form,item=data.stock_items[event.target.value];if(item){form.elements.purchase_unit.value=["package","fardo","caixa","pacote"].includes(item.purchase_unit)?"package":"direct";form.elements.units_per_package.value=Number(item.units_per_package||1)}updateBatchPurchaseLineFields(form)}
  if(event.target.matches("[data-form='stock-purchase-line'] [name='purchase_unit'],[data-form='stock-purchase-line'] [name='stock_type']")){const form=event.target.form;if(event.target.name==="stock_type"&&!form.elements.id.value&&form.elements.stock_category)form.elements.stock_category.value=event.target.value==="weight"?"Comida":"Bebida";updateBatchPurchaseLineFields(form)}
  if(event.target.matches("[data-form='stock-purchase-line'] [name='content_unit']"))updateBatchPurchaseLinePreview(event.target.form)
  if(event.target.matches("[data-stock-type]")){const form=event.target.form,adjust=event.target.value==="adjustment";form.querySelector("[data-stock-quantity]").hidden=adjust;form.querySelector("[data-stock-balance]").hidden=!adjust;form.elements.quantity.required=!adjust;form.elements.new_balance.required=adjust}
});

document.addEventListener("input",event=>{
  if(event.target.matches("[data-form='menu'] [name='component_quantity']"))updateMenuRecipeCosts(event.target.form);
  if(event.target.matches("[data-form='stock-purchase'] [name='quantity'],[data-form='stock-purchase'] [name='units_per_package'],[data-form='stock-purchase'] [name='unit_cost']"))updateStockPurchaseCalculation(event.target.form);
  if(event.target.matches("[data-form='stock-purchase-line'] [name='package_quantity'],[data-form='stock-purchase-line'] [name='units_per_package'],[data-form='stock-purchase-line'] [name='package_cost'],[data-form='stock-purchase-line'] [name='content_per_unit']"))updateBatchPurchaseLinePreview(event.target.form);
  if(event.target.matches("[data-product-search]")){saleSearch=event.target.value;draw();requestAnimationFrame(()=>{const input=document.querySelector("[data-product-search]");if(input){input.focus();input.setSelectionRange(saleSearch.length,saleSearch.length)}})}
  if(event.target.matches("[data-form='stock-item'] [name='entry_quantity'],[data-form='stock-item'] [name='cost_price']")){const form=event.target.form,total=Number(form.elements.entry_quantity.value||0)*Number(form.elements.cost_price.value||0);form.querySelector("[data-manual-stock-total]").textContent=money(Number.isFinite(total)?total:0)}
  if(event.target.matches("[data-form='account-payment'] [name='amount']")){updatePaymentRemaining(event.target.form);updateAccountPaymentChange(event.target.form)}
  if(event.target.matches("[data-form='account-payment'] [name='split_people'],[data-form='account-payment'] [data-allocation-item],[data-form='account-payment'] [data-allocation-toggle]")){if(event.target.matches("[data-allocation-item]")&&event.target.value!==""){const maximum=Number(event.target.max),value=Number(event.target.value);if(Number.isFinite(maximum)&&value>maximum)event.target.value=String(maximum);else if(value<0)event.target.value="0"}updateAccountPaymentFields(event.target.form)}
  if(event.target.matches("[data-form='account-payment'] [name='cash_received']"))updateAccountPaymentChange(event.target.form)
  if(event.target.matches("[data-form='checkout'] [name='cash_received']"))updateCheckoutChange(event.target.form)
});

document.addEventListener("keydown",event=>{
  if(event.key==="Escape"&&modal.open){closeModal();return}
  if(module!=="Frente de caixa"||page!=="sales")return;
  if(event.key==="F2"){event.preventDefault();document.querySelector("[data-product-search]")?.focus()}
  if(event.key==="F4"&&cartLines().length){event.preventDefault();checkoutDialog()}
});

modal.addEventListener("click",event=>{if(event.target===modal)closeModal()});
document.addEventListener("click",event=>{
  const summary=event.target.closest(".kitchen-history > summary");
  if(!summary)return;
  event.preventDefault();
  kitchenHistoryOpen=!kitchenHistoryOpen;
  summary.parentElement.open=kitchenHistoryOpen;
});
document.addEventListener("toggle",event=>{
  if(event.target.matches(".front-kitchen-history"))frontKitchenHistoryOpen=event.target.open;
},true);
async function start(){try{if(inviteToken)await claimInvite();if(token||deviceToken||originToken)await load();else draw()}catch(error){localStorage.removeItem("staffAccessToken");originToken="";module=null;page=null;draw();toast(error.message,true)}}
start();
